// デフォルトの読みデータを取得（データがない場合）
export function getKanjiReading(kanji: string): KanjiReading {
  return kanjiReadings[kanji] || {
    onyomi: [],
    kunyomi: [],
    meanings: [],
    examples: []
  };
}

// 読み問題用：正解以外の選択肢を生成
export function generateReadingChoices(correctReading: string, allReadings: string[], count: number = 4): string[] {
  const choices = [correctReading];
  const availableReadings = allReadings.filter(r => r !== correctReading);

  while (choices.length < count && availableReadings.length > 0) {
    const randomIndex = Math.floor(Math.random() * availableReadings.length);
    choices.push(availableReadings.splice(randomIndex, 1)[0]);
  }

  // シャッフル
  return choices.sort(() => Math.random() - 0.5);
}
